BEGIN;

ALTER TABLE guide_articles
  DROP CONSTRAINT IF EXISTS guide_articles_category_slug_check;

ALTER TABLE guide_articles
  ADD CONSTRAINT guide_articles_category_slug_check
  CHECK (
    category_slug IN (
      'coming-to-germany', 'visas', 'family', 'invitation',
      'embassy-and-appointments', 'documents', 'language-and-certificates',
      'education', 'work-and-career', 'after-arrival', 'recognition',
      'transport-and-driving', 'integration'
    )
  );

INSERT INTO guide_articles (
  legacy_id, slug, category_slug,
  title_uz, title_de, excerpt_uz, excerpt_de, intro_uz, intro_de,
  reading_time_uz, reading_time_de, facts_uz, facts_de, sections_uz, sections_de,
  steps_uz, steps_de, faq_uz, faq_de, sources, related_article_slugs,
  last_reviewed_at, status, featured
)
SELECT
  'driving-licence-uzbekistan-umschreibung', 'uzbek-driving-licence-umschreibung', 'transport-and-driving', 'O‘zbekiston haydovchilik guvohnomasini Germaniyada almashtirish (Umschreibung)', 'Usbekischen Führerschein in Deutschland umschreiben (Umschreibung)', 'O‘zbekiston haydovchilik guvohnomasini Germaniyada tan oldirish va almashtirish: 6 oylik muddat, hujjatlar, Theorie, Praxis va Schlüsselzahl 70 bo‘yicha amaldagi yo‘riqnoma.', 'Aktueller Leitfaden zur Umschreibung eines usbekischen Führerscheins in Deutschland: Sechsmonatsfrist, Unterlagen, Theorie, Praxis und Schlüsselzahl 70.', 'O‘zbekistonda berilgan haydovchilik guvohnomasini Germaniyada Umschreibung qilish jarayoni guvohnoma qayerda berilgani, Wohnsitz va amaldagi FeV qoidalariga bog‘liq. Ushbu qo‘llanma Klasse B uchun odatiy holatni bosqichma-bosqich tushuntiradi va mahalliy Fahrerlaubnisbehörde talablarini alohida tekshirish kerakligini ko‘rsatadi.', 'Die Umschreibung einer in Usbekistan erteilten Fahrerlaubnis hängt vom Ausstellungsstaat, vom ordentlichen Wohnsitz und von der aktuellen FeV ab. Dieser Leitfaden erklärt den typischen Ablauf für Klasse B Schritt für Schritt und weist darauf hin, örtliche Anforderungen bei der Fahrerlaubnisbehörde gesondert zu prüfen.', '8–10 daqiqa', '8–10 Minuten', '[{"label": "Amaldagi asos", "value": "FeV §§ 29 va 31"}, {"label": "Wohnsitzdan keyin", "value": "Odatda 6 oy haydash huquqi"}, {"label": "O‘zbekiston", "value": "2026-09-23 holatiga Anlage 11 ro‘yxatida yo‘q"}, {"label": "Class B Umschreibung", "value": "Nazariy va amaliy imtihon talab qilinadi; majburiy Fahrschule-Ausbildung esa §31(2) bo‘yicha qo‘llanmaydi"}]'::jsonb, '[{"label": "Rechtsgrundlage", "value": "FeV §§ 29 und 31"}, {"label": "Nach Wohnsitznahme", "value": "Fahrberechtigung grundsätzlich noch 6 Monate"}, {"label": "Usbekistan", "value": "Stand 23.09.2026 nicht in Anlage 11 aufgeführt"}, {"label": "Umschreibung Klasse B", "value": "Theoretische und praktische Prüfung erforderlich; die Ausbildungsvorschriften sind nach § 31 Abs. 2 FeV nicht anzuwenden"}]'::jsonb, '{"overview": {"title": "1. Wohnsitzdan keyingi 6 oylik muddat", "paragraphs": ["O‘zbekiston kabi EU/EWRga kirmaydigan davlatda berilgan amaldagi guvohnoma bilan Germaniyada odatiy Wohnsitz tashkil qilingandan keyin haydash huquqi FeV §29(1) bo‘yicha odatda yana olti oy davom etadi. Bu muddat tugagach, Germaniyada haydash uchun nemis Fahrerlaubnis kerak bo‘ladi.", "Faqat Germaniyada 12 oydan ortiq yashamasligingizni ishonarli ko‘rsata olsangiz, Fahrerlaubnisbehörde ariza asosida muddatni ko‘pi bilan yana olti oyga uzaytirishi mumkin."], "items": []}, "eligibility": {"title": "2. O‘zbekiston guvohnomasining holatini tekshirish", "paragraphs": ["2026-yil 23-sentabrda tekshirilgan amaldagi FeV Anlage 11 davlatlar ro‘yxatida O‘zbekiston ko‘rsatilmagan. Shu sababli O‘zbekistonda berilgan odatiy guvohnomani Umschreibung qilishda Anlage 11 bo‘yicha imtihonlardan ozod qilish imtiyozi qo‘llanmaydi.", "FeV §31(2) bo‘yicha bunday davlat guvohnomasi uchun Fahrschule-Ausbildung haqidagi majburiy qoidalar qo‘llanmaydi. Biroq nazariy va amaliy Fahrerlaubnisprüfungdan ozodlik berilmagan."], "items": []}, "requirements": {"title": "3–5. Fahrerlaubnisbehörde, tayyorgarlik va ariza", "paragraphs": ["Ariza odatiy Wohnsitzingiz bo‘yicha vakolatli Fahrerlaubnisbehördega beriladi. BMV ham individual jarayon va hujjatlar bo‘yicha mahalliy idora bilan erta bog‘lanishni tavsiya qiladi.", "Mahalliy tartib, termin, to‘lov va tarjima talabi idoraga qarab farq qilishi mumkin. Masalan, Kreis Rendsburg-Eckernförde Nicht-EU guvohnomalari uchun original guvohnoma, tarjima, Sehtest, Erste-Hilfe va boshqa hujjatlarni ko‘rsatadi."], "items": ["Vakolatli Fahrerlaubnisbehörde sahifasidan aynan ‘Umschreibung einer ausländischen Fahrerlaubnis’ xizmatini toping.", "Termin/ariza usulini va mahalliy hujjatlar ro‘yxatini tekshiring.", "Imtihon kerak bo‘lsa, arizada Fahrschule ko‘rsatilishi talab qilinishi mumkin."]}, "documents": {"title": "4. Hujjatlar checklisti", "paragraphs": ["Quyidagi ro‘yxat Klasse B va O‘zbekiston kabi Anlage 11da bo‘lmagan Nicht-EU davlat guvohnomasi uchun amaldagi federal qoidalar hamda Schleswig-Holstein mahalliy amaliyoti asosida tuzilgan. Yakuniy ro‘yxatni o‘z Fahrerlaubnisbehördeingizdan tekshiring."], "items": ["Shaxsni tasdiqlovchi amaldagi hujjat; pasport topshirilganda mahalliy idora Meldebescheinigung ham so‘rashi mumkin.", "O‘zbekiston haydovchilik guvohnomasining amaldagi originali.", "Aktual biometrik foto.", "Guvohnomaning nemischa tarjimasi — vakolatli idora talab qiladigan shakl va tarjimon maqomini oldindan tekshiring.", "Klasse B uchun Sehtestbescheinigung.", "Erste-Hilfe-Schulung tasdig‘i.", "Mahalliy ariza formasi; imtihonlar uchun zarur bo‘lsa Fahrschule ma’lumoti."]}, "conditions": {"title": "6–8. Theorie, Praxis va nemis Führerscheini", "paragraphs": ["O‘zbekiston Anlage 11da bo‘lmagani sababli Klasse B Umschreibungda nazariy va amaliy imtihon topshiriladi. §31(2) majburiy Fahrschule-Ausbildungni bekor qiladi, lekin imtihonlarning o‘zini bekor qilmaydi.", "Amaliy imtihon texnik jihatdan Fahrschule orqali tashkil etiladi; tayyorgarlik darslarining qonuniy minimumi Umschreibung uchun belgilanmagan bo‘lsa-da, xavfsiz va imtihonga tayyor haydash darajasi zarur.", "Talablar bajarilgach, nemis guvohnomasi §31(4) bo‘yicha xorijiy guvohnomani topshirish evaziga beriladi; idora uni qaytarishi yoki saqlashi tegishli tartibga bog‘liq."], "items": []}, "warnings": {"title": "Schlüsselzahl 70 — alohida tekshiriladigan holat", "paragraphs": ["FeV Anlage 9 bo‘yicha 70 kodi boshqa guvohnomani almashtirish asosida berilgan guvohnomani bildiradi; kodda oldingi guvohnoma raqami va uni bergan davlat belgisi ko‘rsatiladi. Masalan, 70.…UZ O‘zbekiston bilan bog‘liq oldingi guvohnomaga ishora qilishi mumkin.", "Muhim: 70 kodining o‘zi Germaniyada avtomatik ‘tan olinadi’ yoki ‘tan olinmaydi’ degan xulosa uchun yetarli emas. 2026-yil avgustida yangilangan amaldagi FeV §28 EU/EWR guvohnomalarini prinsipial tan oladi, biroq §28(4)dagi istisnolar — jumladan qalbaki asl hujjat, ayrim Wohnsitz holatlari, olib qo‘yish/taqiq kabi vaziyatlar — alohida tekshiriladi. 70.…UZ bo‘lsa, Fahrerlaubnisbehördega hujjatni ko‘rsatib individual holatni aniqlashtiring."], "items": []}}'::jsonb, '{"overview": {"title": "1. Sechs Monate nach Begründung des Wohnsitzes", "paragraphs": ["Mit einer gültigen Fahrerlaubnis aus einem Nicht-EU-/Nicht-EWR-Staat wie Usbekistan besteht die Fahrberechtigung in Deutschland nach Begründung des ordentlichen Wohnsitzes gemäß § 29 Abs. 1 FeV grundsätzlich noch sechs Monate. Danach ist zum Fahren in Deutschland eine deutsche Fahrerlaubnis erforderlich.", "Nur wenn glaubhaft gemacht wird, dass der ordentliche Wohnsitz nicht länger als zwölf Monate in Deutschland bestehen wird, kann die Fahrerlaubnisbehörde die Frist auf Antrag um höchstens weitere sechs Monate verlängern."], "items": []}, "eligibility": {"title": "2. Status der usbekischen Fahrerlaubnis prüfen", "paragraphs": ["In der am 23. September 2026 geprüften aktuellen Staatenliste der Anlage 11 FeV ist Usbekistan nicht aufgeführt. Die dort vorgesehenen Prüfungsbefreiungen gelten daher für eine regulär in Usbekistan erteilte Fahrerlaubnis nicht.", "Nach § 31 Abs. 2 FeV sind bei Fahrerlaubnissen aus nicht in Anlage 11 aufgeführten Staaten die Vorschriften über die Ausbildung nicht anzuwenden. Eine Befreiung von der theoretischen und praktischen Fahrerlaubnisprüfung folgt daraus jedoch nicht."], "items": []}, "requirements": {"title": "3–5. Fahrerlaubnisbehörde, Vorbereitung und Antrag", "paragraphs": ["Der Antrag wird bei der für den ordentlichen Wohnsitz zuständigen Fahrerlaubnisbehörde gestellt. Auch das BMV empfiehlt, sich für das konkrete Verfahren und die Unterlagen frühzeitig an die örtlich zuständige Behörde zu wenden.", "Termin, Gebühren und einzelne Nachweise können örtlich unterschiedlich gehandhabt werden. Der Kreis Rendsburg-Eckernförde nennt für Nicht-EU-Fahrerlaubnisse unter anderem Originalführerschein, Übersetzung, Sehtest und Erste-Hilfe-Nachweis."], "items": ["Auf der Website der zuständigen Fahrerlaubnisbehörde den Dienst ‘Umschreibung einer ausländischen Fahrerlaubnis’ aufrufen.", "Termin beziehungsweise Antragsweg und die lokale Unterlagenliste prüfen.", "Wenn Prüfungen erforderlich sind, kann im Antrag die Benennung einer Fahrschule verlangt werden."]}, "documents": {"title": "4. Unterlagen-Checkliste", "paragraphs": ["Die folgende Liste orientiert sich für Klasse B und einen Nicht-EU-Staat außerhalb der Anlage 11 an den aktuellen Bundesregeln sowie an der Verwaltungspraxis in Schleswig-Holstein. Maßgeblich bleibt die Liste Ihrer zuständigen Fahrerlaubnisbehörde."], "items": ["Gültiges Identitätsdokument; bei Vorlage eines Reisepasses kann die örtliche Behörde zusätzlich eine Meldebescheinigung verlangen.", "Gültiger usbekischer Führerschein im Original.", "Aktuelles biometrisches Lichtbild.", "Deutsche Übersetzung des Führerscheins — zulässige Übersetzerstelle und Form vorab mit der Behörde klären.", "Sehtestbescheinigung für Klasse B.", "Nachweis über die Schulung in Erster Hilfe.", "Örtliches Antragsformular; bei erforderlichen Prüfungen gegebenenfalls Angaben zur Fahrschule."]}, "conditions": {"title": "6–8. Theorie, Praxis und deutscher Führerschein", "paragraphs": ["Da Usbekistan nicht in Anlage 11 aufgeführt ist, sind bei der Umschreibung der Klasse B die theoretische und die praktische Prüfung abzulegen. § 31 Abs. 2 FeV nimmt lediglich die Ausbildungsvorschriften aus, nicht die Prüfungen selbst.", "Die praktische Prüfung wird organisatorisch über eine Fahrschule abgewickelt. Gesetzlich vorgeschriebene Mindest-Ausbildungsstunden wie bei einer Ersterteilung gelten für diese Umschreibung nicht; die Prüfungsreife muss dennoch gegeben sein.", "Nach Erfüllung der Voraussetzungen wird der deutsche Führerschein gemäß § 31 Abs. 4 FeV grundsätzlich nur gegen Abgabe des ausländischen Führerscheins ausgehändigt; dessen weiterer Verbleib richtet sich nach dem gesetzlichen Verfahren."], "items": []}, "warnings": {"title": "Schlüsselzahl 70 — gesondert prüfen", "paragraphs": ["Nach Anlage 9 FeV kennzeichnet die Schlüsselzahl 70 den Umtausch eines zuvor erteilten Führerscheins; eingetragen werden die Nummer des früheren Führerscheins und das Länderkennzeichen der ausstellenden Stelle. Ein Eintrag 70.…UZ kann daher auf einen ursprünglich usbekischen Führerschein hinweisen.", "Wichtig: Die Schlüsselzahl 70 allein erlaubt keine pauschale Aussage ‘anerkannt’ oder ‘nicht anerkannt’. Nach der im August 2026 geänderten aktuellen Fassung des § 28 FeV werden EU-/EWR-Fahrerlaubnisse grundsätzlich anerkannt; die Ausnahmen des § 28 Abs. 4, etwa bei gefälschtem Ausgangsführerschein, bestimmten Wohnsitzkonstellationen oder bestehenden Entziehungen/Fahrverboten, bleiben gesondert zu prüfen. Bei 70.…UZ sollte die Fahrerlaubnisbehörde den konkreten Fall prüfen."], "items": []}}'::jsonb, '[{"title": "1. 6 oylik muddatni hisoblang", "description": "Oddiy Wohnsitz Germaniyada qachon tashkil qilinganini aniqlang. Nicht-EU/EWR guvohnomasi bilan haydash huquqi odatda shu sanadan olti oy davom etadi."}, {"title": "2. O‘zbekiston statusini tekshiring", "description": "Current Anlage 11ni tekshiring. 23.09.2026 holatiga O‘zbekiston ro‘yxatda yo‘q; shu sababli Klasse B uchun imtihon imtiyozi mavjud emas."}, {"title": "3. Fahrerlaubnisbehördeni toping", "description": "Hauptwohnsitzingiz bo‘yicha Stadt yoki Kreis Fahrerlaubnisbehörde sahifasidan Umschreibung xizmatini toping."}, {"title": "4. Hujjatlarni tayyorlang", "description": "Original guvohnoma, ID, foto, Sehtest, Erste Hilfe va talab qilinadigan tarjimani mahalliy checklist bo‘yicha tayyorlang."}, {"title": "5. Antrag topshiring", "description": "Arizani mahalliy tartib bo‘yicha yuboring yoki terminda topshiring; imtihon kerak bo‘lsa Fahrschule ma’lumoti talab qilinishi mumkin."}, {"title": "6. Nazariy imtihon", "description": "Behörde Prüfauftragni ochgach, nazariy imtihonga tayyorlaning va topshiring. Umschreibung uchun majburiy nazariy darslar belgilanmagan."}, {"title": "7. Amaliy imtihon", "description": "Amaliy imtihon Fahrschule va Prüfstelle orqali tashkil qilinadi. Majburiy minimal darslar yo‘q, ammo imtihon darajasida xavfsiz haydash zarur."}, {"title": "8. Nemis Führerscheinini oling", "description": "Barcha talab va imtihonlar bajarilgach, nemis guvohnomasi xorijiy original guvohnomani topshirish evaziga beriladi."}]'::jsonb, '[{"title": "1. Sechsmonatsfrist bestimmen", "description": "Klären Sie, wann der ordentliche Wohnsitz in Deutschland begründet wurde. Die Fahrberechtigung mit der Nicht-EU-/EWR-Fahrerlaubnis besteht grundsätzlich sechs Monate ab diesem Zeitpunkt."}, {"title": "2. Status Usbekistans prüfen", "description": "Prüfen Sie die aktuelle Anlage 11. Stand 23.09.2026 ist Usbekistan nicht aufgeführt; für Klasse B besteht daher keine Prüfungsbefreiung nach Anlage 11."}, {"title": "3. Fahrerlaubnisbehörde finden", "description": "Rufen Sie bei Stadt oder Kreis Ihres Hauptwohnsitzes den Dienst zur Umschreibung einer ausländischen Fahrerlaubnis auf."}, {"title": "4. Unterlagen vorbereiten", "description": "Bereiten Sie Originalführerschein, Identitätsnachweis, Foto, Sehtest, Erste Hilfe und die verlangte Übersetzung anhand der örtlichen Checkliste vor."}, {"title": "5. Antrag stellen", "description": "Reichen Sie den Antrag nach dem örtlichen Verfahren ein; bei erforderlichen Prüfungen kann die Angabe einer Fahrschule verlangt werden."}, {"title": "6. Theoretische Prüfung", "description": "Nach Freigabe des Prüfauftrags durch die Behörde bereiten Sie sich auf die Theorieprüfung vor und legen sie ab. Eine vorgeschriebene Fahrschulausbildung entfällt bei dieser Umschreibung."}, {"title": "7. Praktische Prüfung", "description": "Die praktische Prüfung wird über Fahrschule und Prüfstelle organisiert. Vorgeschriebene Mindeststunden entfallen, die Prüfungsreife ist dennoch erforderlich."}, {"title": "8. Deutschen Führerschein erhalten", "description": "Nach Erfüllung aller Voraussetzungen und bestandenen Prüfungen wird der deutsche Führerschein grundsätzlich gegen Abgabe des ausländischen Originals ausgehändigt."}]'::jsonb, '[{"question": "6 oy tugagach O‘zbekiston guvohnomasi bilan haydash mumkinmi?", "answer": "Odatda yo‘q. FeV §29(1) bo‘yicha Wohnsitzdan keyingi olti oylik muddat tugagach, xorijiy guvohnoma Germaniyada haydash huquqini bermaydi. Tor doiradagi vaqtinchalik yashash holatida ariza bilan uzaytirish mumkin."}, {"question": "Fahrschulega boshidan to‘liq o‘qish shartmi?", "answer": "Yo‘q. FeV §31(2) Anlage 11da bo‘lmagan davlat guvohnomasi uchun Ausbildung qoidalarini qo‘llamaydi. Ammo O‘zbekiston uchun nazariy va amaliy imtihonlar talab qilinadi."}, {"question": "70.…UZ bo‘lsa, EU guvohnomam Germaniyada avtomatik yaroqsizmi?", "answer": "Bunday umumlashtirish to‘g‘ri emas. 70 kod almashuv tarixini ko‘rsatadi. Amaldagi §28 FeV va undagi istisnolar asosida individual holat tekshirilishi kerak."}]'::jsonb, '[{"question": "Darf ich nach Ablauf der sechs Monate mit dem usbekischen Führerschein weiterfahren?", "answer": "Grundsätzlich nein. Nach Ablauf der Sechsmonatsfrist des § 29 Abs. 1 FeV vermittelt die ausländische Fahrerlaubnis in Deutschland keine Fahrberechtigung mehr. Für bestimmte nur vorübergehende Wohnsitzfälle ist auf Antrag eine begrenzte Verlängerung möglich."}, {"question": "Muss ich die Fahrschulausbildung vollständig neu absolvieren?", "answer": "Nein. § 31 Abs. 2 FeV nimmt bei Fahrerlaubnissen aus Staaten außerhalb der Anlage 11 die Ausbildungsvorschriften aus. Für Usbekistan bleiben die theoretische und praktische Prüfung jedoch erforderlich."}, {"question": "Ist ein EU-Führerschein mit 70.…UZ in Deutschland automatisch ungültig?", "answer": "Eine solche Pauschalaussage ist nicht richtig. Code 70 dokumentiert den Umtausch. Entscheidend sind die aktuelle Fassung des § 28 FeV und die dort geregelten Ausnahmen im konkreten Fall."}]'::jsonb, '[{"title": "§ 29 FeV – Ausländische Fahrerlaubnisse", "organization": "Bundesministerium der Justiz / Bundesamt für Justiz", "url": "https://www.gesetze-im-internet.de/fev_2010/__29.html", "language": "de"}, {"title": "§ 31 FeV – Fahrerlaubnisse aus Staaten außerhalb des EWR", "organization": "Bundesministerium der Justiz / Bundesamt für Justiz", "url": "https://www.gesetze-im-internet.de/fev_2010/__31.html", "language": "de"}, {"title": "Anlage 11 FeV – Staatenliste", "organization": "Bundesministerium der Justiz / Bundesamt für Justiz", "url": "https://www.gesetze-im-internet.de/fev_2010/anlage_11.html", "language": "de"}, {"title": "Anlage 9 FeV – Schlüsselzahlen, insbesondere 70", "organization": "Bundesministerium der Justiz / Bundesamt für Justiz", "url": "https://www.gesetze-im-internet.de/fev_2010/anlage_9.html", "language": "de"}, {"title": "Gültigkeit ausländischer Fahrerlaubnisse in Deutschland", "organization": "Bundesministerium für Verkehr", "url": "https://www.bmv.de/SharedDocs/DE/Artikel/StV/Strassenverkehr/gueltigkeit-auslaendischer-fahrerlaubnisse-in-deutschland.htm", "language": "de"}, {"title": "Fahrerlaubnisbehörde – Umschreibung einer ausländischen Fahrerlaubnis", "organization": "Kreis Rendsburg-Eckernförde", "url": "https://www.kreis-rendsburg-eckernfoerde.de/bauen-mobilitaet/verkehr/fahrerlaubnisbehoerde", "language": "de"}]'::jsonb, ARRAY[]::text[], '2026-09-23', 'published', FALSE
WHERE NOT EXISTS (
  SELECT 1 FROM guide_articles WHERE slug = 'uzbek-driving-licence-umschreibung'
);

COMMIT;
